#!/usr/bin/env bash
# lmparticle has no third-party source dependencies: the cross-section tables are committed in data/xcom.csv
# (generated by scripts/fetch-xcom.py from public NIST XCOM data). This script exists so the CI steps are uniform.
set -eu
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
[ -s "$HERE/data/xcom.csv" ] || { echo "data/xcom.csv missing" >&2; exit 1; }
[ "${1:-}" = "--verify" ] && echo "no third-party dependencies; data/xcom.csv present" || echo "no third-party dependencies to fetch"
exit 0
